/** Original immutable context configuration and independent decision ledger. No execution is implied.
 * Caller must use EnterpriseAccess's tenant-locked transaction. No production fallback or autoapproval. */
public final class FormalEvaluationContextStore {
 private final JdbcTemplate db;private final PermissionSchema json;private final FormalEvaluationContextSchema schema;
 private final FormalEvaluationContextDependencies dependencies;private final ResourceReadAuthority resources;
 private final PermissionMapper permissions;private final PermissionAuthority grants;private final PlatformMemberIdentityStatus identities;
 private final JsonMapper decoder=JsonMapper.builder().addModule(new JavaTimeModule()).propertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE).build();
 public FormalEvaluationContextStore(DataSource data,PermissionSchema json,FormalEvaluationContextSchema schema,FormalEvaluationContextDependencies dependencies,ResourceReadAuthority resources,PermissionMapper permissions,PermissionAuthority grants,PlatformMemberIdentityStatus identities){this(new JdbcTemplate(data),json,schema,dependencies,resources,permissions,grants,identities);}
 FormalEvaluationContextStore(JdbcTemplate db,PermissionSchema json,FormalEvaluationContextSchema schema,FormalEvaluationContextDependencies dependencies,ResourceReadAuthority resources,PermissionMapper permissions,PermissionAuthority grants,PlatformMemberIdentityStatus identities){this.db=db;this.json=json;this.schema=schema;this.dependencies=dependencies;this.resources=resources;this.permissions=permissions;this.grants=grants;this.identities=identities;db.setQueryTimeout(5);}
 public record Receipt(PermissionProtocol.Basis binding,String status,String revision,String operationId){}
 private record Loaded(Map<String,Object> row,Definition definition,Map<String,Object> state,List<Map<String,Object>> decisions,String canonical){}

 public Receipt author(EnterpriseAccess.Admission a,String key,byte[] body)throws Exception {
  current(a);var request=schema.author(body);var grant=authorize(a,request.definition().projectId(),"agent.configure");lock(a);key(key);
  String requestJson=json.canonicalObject(request),requestHash=sha(requestJson);var prior=prior(a,"formal_evaluation_context_version",key,requestHash);
  if(prior!=null){var loaded=load(a,text(prior,"version_id"));dependencies.require(a,loaded.definition());return receipt(loaded,prior);}
  var checked=dependencies.require(a,request.definition());String version=id();LocalDateTime now=now();
  var fixed=json.object().put("schema_version","1.0.0").put("tenant_id",a.context().tenant_id()).put("version_id",version).put("created_by",a.actorId()).put("created_at",instant(now)).put("classification",checked.classification());fixed.set("definition",json.tree(request.definition()));
  var auth=authorization(a,grant,checked.authorizations());var row=journal(a,request.definition().projectId(),version,"AUTHOR",key,requestJson,fixed,auth,checked.classification(),now);
  row.put("version_id",version);row.put("candidate_version",request.definition().candidate().version_id());row.put("candidate_sha256",request.definition().candidate().content_sha256());row.put("policy_version",request.definition().executionPolicy().version_id());row.put("policy_sha256",request.definition().executionPolicy().content_sha256());
  changed(db.update("INSERT INTO version_registry (tenant_id,version_id,owner_project_id,entity_kind,content_sha256) VALUES (?,?,?,'EVALUATION_CONTEXT_BINDING',?)",a.context().tenant_id(),version,request.definition().projectId(),row.get("content_sha256")));
  insert("formal_evaluation_context_version",row);
  for(var b:checked.versions())changed(db.update("INSERT INTO lineage_edge (tenant_id,consumer_version_id,upstream_version_id,relation_kind,actor_id,decision_ref,created_at) VALUES (?,?,?,'DEPENDS_ON',?,NULL,?)",a.context().tenant_id(),version,b.version_id(),a.actorId(),now));
  changed(db.update("INSERT INTO formal_evaluation_context_state (tenant_id,project_id,version_id,status,revision,latest_decision_id,updated_at,schema_version,schema_manifest_sha256,created_by,created_at,classification) VALUES (?,?,?,'DRAFT',1,NULL,?,'1.0.0',?,?,?,?)",a.context().tenant_id(),request.definition().projectId(),version,now,schema.manifest(),a.actorId(),now,checked.classification()));
  checked.requireCurrent();var loaded=load(a,version);advance(a);return receipt(loaded,row);
 }
 public Receipt decide(EnterpriseAccess.Admission a,String key,byte[] body)throws Exception {
  current(a);var request=schema.decide(body);var loaded=load(a,request.binding().version_id());if(!request.binding().content_sha256().equals(loaded.row().get("content_sha256")))bad();
  var grant=authorize(a,loaded.definition().projectId(),"agent.publish");lock(a);key(key);String raw=json.canonicalObject(request);var prior=prior(a,"formal_evaluation_context_decision",key,sha(raw));
  if(prior!=null){if(!request.binding().version_id().equals(prior.get("version_id"))||loaded.decisions().stream().noneMatch(d->d.get("record_id").equals(prior.get("record_id"))))bad();return receipt(loaded,prior);}
  if(!request.expectedRevision().equals(number(loaded.state(),"revision").toString()))deny(ErrorCode.REVISION_CONFLICT);
  String status=transition(text(loaded.state(),"status"),request.decision());
  var checked=dependencies.require(a,loaded.definition());if(a.actorId().equals(loaded.row().get("created_by"))||a.actorId().equals(checked.candidateAuthor()))deny(ErrorCode.ACCESS_DENIED);
  String record=id();LocalDateTime now=now();BigInteger before=number(loaded.state(),"revision"),after=before.add(BigInteger.ONE);
  var content=json.object().put("schema_version","1.0.0").put("tenant_id",a.context().tenant_id()).put("version_id",request.binding().version_id()).put("binding_sha256",request.binding().content_sha256()).put("record_id",record).put("previous_status",text(loaded.state(),"status")).put("previous_revision",before.toString()).put("decision",request.decision()).put("status",status).put("revision",after.toString()).put("actor_id",a.actorId()).put("decided_at",instant(now)).put("reason",request.reason());
  var row=journal(a,loaded.definition().projectId(),record,"DECISION",key,raw,content,authorization(a,grant,checked.authorizations()),text(loaded.row(),"classification"),now);
  row.put("version_id",request.binding().version_id());row.put("before_revision",before);row.put("after_revision",after);row.put("decision",request.decision());row.put("status",status);insert("formal_evaluation_context_decision",row);
  changed(db.update("UPDATE formal_evaluation_context_state SET status=?,revision=?,latest_decision_id=?,updated_at=? WHERE tenant_id=? AND version_id=? AND status=? AND revision=?",status,after,record,now,a.context().tenant_id(),request.binding().version_id(),text(loaded.state(),"status"),before));
  checked.requireCurrent();loaded=load(a,request.binding().version_id());if("APPROVED".equals(status))approval(a,loaded);advance(a);return receipt(loaded,row);
 }
 public JsonNode read(EnterpriseAccess.Admission a,String version)throws Exception{var loaded=load(a,version);var v=json.object();v.set("fixed",schema.read(text(loaded.row(),"content_json")));v.put("status",text(loaded.state(),"status"));v.put("revision",number(loaded.state(),"revision").toString());return v;}
 public Approved requireApproved(EnterpriseAccess.Admission a,PermissionProtocol.Basis binding,PermissionProtocol.Basis candidate,PermissionProtocol.Basis policy)throws Exception {
  var loaded=load(a,binding.version_id(),"EVALUATION_RESULTS");if(!binding.content_sha256().equals(loaded.row().get("content_sha256"))||!candidate.equals(loaded.definition().candidate())||!policy.equals(loaded.definition().executionPolicy()))bad();
  var checked=dependencies.require(a,loaded.definition());var grant=approval(a,loaded);checked.requireCurrent();return new Approved(this,a,binding,candidate,policy,loaded.definition(),loaded.canonical(),json.canonical(AgentPublicationWitness.tree(grant)),checked.authorizations());
 }
 public static final class Approved {
  private final FormalEvaluationContextStore owner;private final EnterpriseAccess.Admission actor;private final TenantScope scope;private final Thread thread;
  private final PermissionProtocol.Basis binding,candidate,policy;private final Definition definition;private final String original,grant;private final JsonNode dependencies;
  private Approved(FormalEvaluationContextStore owner,EnterpriseAccess.Admission actor,PermissionProtocol.Basis binding,PermissionProtocol.Basis candidate,PermissionProtocol.Basis policy,Definition definition,String original,String grant,JsonNode dependencies){this.owner=owner;this.actor=actor;this.binding=binding;this.candidate=candidate;this.policy=policy;this.definition=definition;this.original=original;this.grant=grant;this.dependencies=dependencies.deepCopy();scope=TenantScope.requireCurrent();thread=Thread.currentThread();}
  public PermissionProtocol.Basis binding(){return binding;}public Definition definition(){return definition;}
  public Node node(String kind){return definition.nodeBindings().stream().filter(n->n.nodeKind().equals(kind)).findFirst().orElseThrow(()->new TenantAccessException(ErrorCode.OBJECT_UNAVAILABLE));}
  public void requireConsumer(EnterpriseAccess.Admission a,PermissionProtocol.Basis candidate,PermissionProtocol.Basis policy)throws Exception{if(a!=actor||!this.candidate.equals(candidate)||!this.policy.equals(policy))deny(ErrorCode.ACCESS_DENIED);requireUnchanged();}
  public void requireUnchanged()throws Exception{if(Thread.currentThread()!=thread||TenantScope.requireCurrent()!=scope)deny(ErrorCode.ACCESS_DENIED);var fresh=owner.requireApproved(actor,binding,candidate,policy);if(!original.equals(fresh.original)||!grant.equals(fresh.grant)||!dependencies.equals(fresh.dependencies))deny(ErrorCode.SCOPE_STALE);}
 }
 private Loaded load(EnterpriseAccess.Admission a,String version)throws Exception {return load(a,version,"AGENT_PUBLICATION");}
 private Loaded load(EnterpriseAccess.Admission a,String version,String purpose)throws Exception {
  current(a);WireValues.uuid(version);String tenant=a.context().tenant_id();var row=one(db.queryForList("SELECT * FROM formal_evaluation_context_version WHERE tenant_id=? AND version_id=? LIMIT 2",tenant,version));
  resources.require(a,governance(a.context().tenant_id(),text(row,"project_id")),"project.read",purpose);verifyJournal(a,row,"AUTHOR");var fixed=schema.read(text(row,"content_json"));var definition=schema.definition(fixed.required("definition"));
  if(fixed.size()!=7||!"1.0.0".equals(fixed.required("schema_version").asText()))bad();
  if(!tenant.equals(fixed.required("tenant_id").asText())||!version.equals(fixed.required("version_id").asText())||!text(row,"created_by").equals(fixed.required("created_by").asText())||!instant(time(row,"created_at")).equals(fixed.required("created_at").asText())||!text(row,"classification").equals(fixed.required("classification").asText())||!definition.projectId().equals(row.get("project_id"))||!definition.candidate().version_id().equals(row.get("candidate_version"))||!definition.candidate().content_sha256().equals(row.get("candidate_sha256"))||!definition.executionPolicy().version_id().equals(row.get("policy_version"))||!definition.executionPolicy().content_sha256().equals(row.get("policy_sha256")))bad();
  var intent=schema.author(text(row,"request_json").getBytes(java.nio.charset.StandardCharsets.UTF_8));if(!intent.definition().equals(definition))bad();
  var registry=one(db.queryForList("SELECT * FROM version_registry WHERE tenant_id=? AND version_id=? LIMIT 2",tenant,version));if(!definition.projectId().equals(registry.get("owner_project_id"))||!"EVALUATION_CONTEXT_BINDING".equals(registry.get("entity_kind"))||!row.get("content_sha256").equals(registry.get("content_sha256")))bad();
  var expected=new TreeSet<String>();expected.add(definition.candidate().version_id());expected.add(definition.executionPolicy().version_id());for(var n:definition.nodeBindings())for(var b:List.of(n.role(),n.prompt(),n.contextAssembler()))expected.add(b.version_id());
  var parents=db.queryForList("SELECT upstream_version_id,relation_kind,actor_id,decision_ref,created_at FROM lineage_edge WHERE tenant_id=? AND consumer_version_id=? ORDER BY upstream_version_id LIMIT 33",tenant,version);var actual=new TreeSet<String>();for(var p:parents){if(!"DEPENDS_ON".equals(p.get("relation_kind"))||!row.get("created_by").equals(p.get("actor_id"))||p.get("decision_ref")!=null||!time(row,"created_at").equals(time(p,"created_at"))||!actual.add(text(p,"upstream_version_id")))bad();}if(!expected.equals(actual))bad();
  var state=one(db.queryForList("SELECT * FROM formal_evaluation_context_state WHERE tenant_id=? AND version_id=? LIMIT 2",tenant,version));if(!row.get("project_id").equals(state.get("project_id"))||!row.get("created_by").equals(state.get("created_by"))||!time(row,"created_at").equals(time(state,"created_at"))||!row.get("classification").equals(state.get("classification"))||!row.get("schema_version").equals(state.get("schema_version"))||!row.get("schema_manifest_sha256").equals(state.get("schema_manifest_sha256")))bad();var decisions=db.queryForList("SELECT * FROM formal_evaluation_context_decision WHERE tenant_id=? AND version_id=? ORDER BY after_revision LIMIT 3",tenant,version);if(decisions.size()>2)bad();
  String status="DRAFT",last=null;BigInteger revision=BigInteger.ONE;LocalDateTime updated=time(row,"created_at");
  for(var d:decisions){verifyJournal(a,d,"DECISION");var content=schema.read(text(d,"content_json"));if(content.size()!=13||!"1.0.0".equals(content.required("schema_version").asText()))bad();var request=schema.decide(text(d,"request_json").getBytes(java.nio.charset.StandardCharsets.UTF_8));String next=transition(status,text(d,"decision"));
   if(!tenant.equals(content.required("tenant_id").asText())||!definition.projectId().equals(d.get("project_id"))||!version.equals(content.required("version_id").asText())||!row.get("content_sha256").equals(content.required("binding_sha256").asText())||!request.binding().equals(new PermissionProtocol.Basis(version,text(row,"content_sha256")))||!request.expectedRevision().equals(revision.toString())||!request.decision().equals(d.get("decision"))||!request.reason().equals(content.required("reason").asText())||!content.required("previous_status").asText().equals(status)||!content.required("previous_revision").asText().equals(revision.toString())||!revision.equals(number(d,"before_revision"))||!revision.add(BigInteger.ONE).equals(number(d,"after_revision"))||!content.required("revision").asText().equals(number(d,"after_revision").toString())||!next.equals(d.get("status"))||!next.equals(content.required("status").asText())||!d.get("decision").equals(content.required("decision").asText())||!d.get("record_id").equals(content.required("record_id").asText())||!d.get("created_by").equals(content.required("actor_id").asText())||!instant(time(d,"created_at")).equals(content.required("decided_at").asText())||time(d,"created_at").isBefore(updated)||row.get("created_by").equals(d.get("created_by"))||!row.get("classification").equals(d.get("classification")))bad();
   status=next;revision=revision.add(BigInteger.ONE);last=text(d,"record_id");updated=time(d,"created_at");
  }
  if(!status.equals(state.get("status"))||!revision.equals(number(state,"revision"))||!Objects.equals(last,state.get("latest_decision_id"))||!updated.equals(time(state,"updated_at")))bad();
  var original=json.object();original.set("root",AgentPublicationWitness.tree(row));original.set("state",AgentPublicationWitness.tree(state));original.set("decisions",AgentPublicationWitness.tree(decisions));return new Loaded(row,definition,state,List.copyOf(decisions),json.canonical(original));
 }
 private PermissionProtocol.GrantRow approval(EnterpriseAccess.Admission a,Loaded loaded)throws Exception {
  if(!"APPROVED".equals(loaded.state().get("status"))||loaded.decisions().size()!=1)deny(ErrorCode.SOURCE_NOT_READY);var d=loaded.decisions().get(0);String actor=text(d,"created_by");var auth=schema.read(text(d,"authorizations_json"));var original=decoder.treeToValue(auth.required("governance"),PermissionProtocol.GrantRow.class);var member=one(permissions.targetMember(actor));var binding=one(permissions.targetBinding(actor));LocalDateTime now=now();
  if(!a.context().tenant_id().equals(member.tenantId())||!actor.equals(member.userId())||!"ACTIVE".equals(member.status())||member.validFrom().isAfter(now)||member.validTo()!=null&&!member.validTo().isAfter(now)||!actor.equals(binding.userId())||!"ACTIVE".equals(binding.status())||!identities.active(new AuthenticatedIdentityBinding.View(binding.mode(),binding.userId(),binding.issuer(),binding.subject())))deny(ErrorCode.ACCESS_DENIED);
  var grant=one(permissions.currentGrant(original.grantId()));grants.requireResource(governance(a.context().tenant_id(),loaded.definition().projectId()),actor,binding.mode(),"agent.publish","AGENT_PUBLICATION",List.of(grant),now);if(!AgentPublicationWitness.tree(original).equals(AgentPublicationWitness.tree(grant)))deny(ErrorCode.SCOPE_STALE);
  var checked=dependencies.require(a,loaded.definition());if(actor.equals(checked.candidateAuthor()))deny(ErrorCode.ACCESS_DENIED);return grant;
 }
 private Map<String,Object> journal(EnterpriseAccess.Admission a,String project,String record,String kind,String key,String request,JsonNode content,JsonNode auth,String classification,LocalDateTime now)throws Exception {
  String operation=id(),audit=id(),event=id(),contentJson=json.canonical(content),authJson=json.canonical(auth),action="evaluation.context."+kind.toLowerCase(Locale.ROOT);var receipt=receiptDocument(kind,content,operation,sha(contentJson));
  var row=new LinkedHashMap<String,Object>();row.put("tenant_id",a.context().tenant_id());row.put("project_id",project);row.put("record_id",record);row.put("operation_id",operation);row.put("idempotency_key",key);row.put("request_json",request);row.put("request_sha256",sha(request));row.put("content_json",contentJson);row.put("content_sha256",sha(contentJson));row.put("authorizations_json",authJson);row.put("authorizations_sha256",sha(authJson));row.put("receipt_json",json.canonical(receipt));row.put("audit_id",audit);row.put("event_id",event);row.put("schema_version","1.0.0");row.put("schema_manifest_sha256",schema.manifest());row.put("created_by",a.actorId());row.put("created_at",now);row.put("classification",classification);
  changed(db.update("INSERT INTO operation_record (tenant_id,operation_id,subject_id,operation_name,idempotency_key,request_sha256,state,http_status,response_ref,target_id,error_code,schema_version,schema_manifest_sha256,created_by,created_at,classification,revision,updated_at) VALUES (?,?,?,?,?,?,'COMPLETED',201,?,?,NULL,'1.0.0',?,?,?,?,1,?)",a.context().tenant_id(),operation,a.actorId(),action,key,row.get("request_sha256"),row.get("receipt_json"),record,schema.manifest(),a.actorId(),now,classification,now));
  String evidence=json.canonical(event(row,kind));
  changed(db.update("INSERT INTO audit_event (tenant_id,project_id,audit_id,subject_id,action,resource_ref,result,request_id,trace_id,schema_version,schema_manifest_sha256,created_by,created_at,classification) VALUES (?,?,?,?,?,?,'SUCCESS',?,?,'1.0.0',?,?,?,?)",a.context().tenant_id(),project,audit,a.actorId(),action,evidence,operation,operation,schema.manifest(),a.actorId(),now,classification));
  changed(db.update("INSERT INTO outbox_event (tenant_id,event_id,aggregate_id,aggregate_revision,event_type,payload,occurred_at) VALUES (?,?,?,1,?,?,?)",a.context().tenant_id(),event,record,action,evidence,now));return row;
 }
 private void verifyJournal(EnterpriseAccess.Admission a,Map<String,Object> row,String kind)throws Exception {
  String tenant=a.context().tenant_id(),actor=text(row,"created_by"),record=text(row,"record_id"),op=text(row,"operation_id"),action="evaluation.context."+kind.toLowerCase(Locale.ROOT);
  if(!tenant.equals(row.get("tenant_id"))||!"1.0.0".equals(row.get("schema_version"))||!schema.manifest().equals(row.get("schema_manifest_sha256")))bad();
  for(String name:List.of("request","content","authorizations")){String raw=text(row,name+"_json");if(raw.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>1048576||!raw.equals(json.canonical(schema.read(raw)))||!sha(raw).equals(row.get(name+"_sha256")))bad();}
  var receipt=receiptDocument(kind,schema.read(text(row,"content_json")),op,text(row,"content_sha256"));if(!receipt.equals(schema.read(text(row,"receipt_json"))))bad();
  var operation=one(db.queryForList("SELECT * FROM operation_record WHERE tenant_id=? AND operation_id=? LIMIT 2",tenant,op));
  if(!actor.equals(operation.get("subject_id"))||!actor.equals(operation.get("created_by"))||!action.equals(operation.get("operation_name"))||!row.get("idempotency_key").equals(operation.get("idempotency_key"))||!row.get("request_sha256").equals(operation.get("request_sha256"))||!"COMPLETED".equals(operation.get("state"))||!BigInteger.valueOf(201).equals(number(operation,"http_status"))||!receipt.equals(schema.read(text(operation,"response_ref")))||!record.equals(operation.get("target_id"))||operation.get("error_code")!=null||!"1.0.0".equals(operation.get("schema_version"))||!schema.manifest().equals(operation.get("schema_manifest_sha256"))||!row.get("classification").equals(operation.get("classification"))||!time(row,"created_at").equals(time(operation,"created_at"))||!time(row,"created_at").equals(time(operation,"updated_at"))||!BigInteger.ONE.equals(number(operation,"revision")))bad();
  var audit=one(db.queryForList("SELECT * FROM audit_event WHERE tenant_id=? AND audit_id=? LIMIT 2",tenant,row.get("audit_id")));var emitted=one(db.queryForList("SELECT * FROM outbox_event WHERE tenant_id=? AND event_id=? LIMIT 2",tenant,row.get("event_id")));var event=event(row,kind);
  if(!row.get("project_id").equals(audit.get("project_id"))||!actor.equals(audit.get("subject_id"))||!actor.equals(audit.get("created_by"))||!action.equals(audit.get("action"))||!"SUCCESS".equals(audit.get("result"))||!op.equals(audit.get("request_id"))||!op.equals(audit.get("trace_id"))||!"1.0.0".equals(audit.get("schema_version"))||!schema.manifest().equals(audit.get("schema_manifest_sha256"))||!time(row,"created_at").equals(time(audit,"created_at"))||!row.get("classification").equals(audit.get("classification"))||!event.equals(schema.read(text(audit,"resource_ref"))))bad();
  if(!record.equals(emitted.get("aggregate_id"))||!BigInteger.ONE.equals(number(emitted,"aggregate_revision"))||!action.equals(emitted.get("event_type"))||!time(row,"created_at").equals(time(emitted,"occurred_at"))||!event.equals(schema.read(text(emitted,"payload"))))bad();
  var auth=schema.read(text(row,"authorizations_json"));var original=decoder.treeToValue(auth.required("governance"),PermissionProtocol.GrantRow.class);String required="AUTHOR".equals(kind)?"agent.configure":"agent.publish";
  if(grants.findResource(governance(tenant,text(row,"project_id")),actor,auth.required("identity_mode").asText(),required,"AGENT_PUBLICATION",List.of(original),time(row,"created_at")).isEmpty())bad();
 }
 private JsonNode event(Map<String,Object> row,String kind){var v=json.object().put("schema_version","1.0.0").put("kind",kind);for(String k:List.of("record_id","operation_id","request_sha256","content_sha256","authorizations_sha256","created_by","classification"))v.put(k,text(row,k));v.put("created_at",instant(time(row,"created_at")));return v;}
 private Map<String,Object> prior(EnterpriseAccess.Admission a,String table,String key,String requestHash){var rows=db.queryForList("SELECT * FROM "+table+" WHERE tenant_id=? AND created_by=? AND idempotency_key=? LIMIT 2",a.context().tenant_id(),a.actorId(),key);if(rows.size()>1)bad();if(rows.isEmpty())return null;var row=rows.get(0);if(!requestHash.equals(row.get("request_sha256")))deny(ErrorCode.IDEMPOTENCY_CONFLICT);return row;}
 private JsonNode authorization(EnterpriseAccess.Admission a,PermissionProtocol.GrantRow grant,JsonNode deps){var v=json.object().put("identity_mode",a.bindingView().mode());v.set("governance",AgentPublicationWitness.tree(grant));v.set("dependencies",deps);return v;}
 private PermissionProtocol.GrantRow authorize(EnterpriseAccess.Admission a,String project,String action)throws IOException{return resources.require(a,governance(a.context().tenant_id(),project),action,"AGENT_PUBLICATION");}
 private void authorizeRead(EnterpriseAccess.Admission a,String project)throws IOException{resources.require(a,governance(a.context().tenant_id(),project),"project.read","AGENT_PUBLICATION");}
 private static PermissionProtocol.Scope governance(String tenant,String project){return new PermissionProtocol.Scope(tenant,project,"PROJECT",project);}
 private static void current(EnterpriseAccess.Admission a){FormalEvaluationExecutionAdmission.current(a);}
 private void lock(EnterpriseAccess.Admission a){if(db.queryForList("SELECT user_id FROM tenant_member WHERE tenant_id=? AND user_id=? FOR UPDATE",a.context().tenant_id(),a.actorId()).size()!=1)deny(ErrorCode.ACCESS_DENIED);}
 private void advance(EnterpriseAccess.Admission a){changed(db.update("UPDATE tenant SET governance_epoch=governance_epoch+1 WHERE tenant_id=? AND auth_epoch=? AND governance_epoch=?",a.context().tenant_id(),a.watermarks().authEpoch(),a.watermarks().governanceEpoch()));}
 private void insert(String table,Map<String,Object> row){var keys=new ArrayList<>(row.keySet());changed(db.update("INSERT INTO "+table+" ("+String.join(",",keys)+") VALUES ("+String.join(",",Collections.nCopies(keys.size(),"?"))+")",keys.stream().map(row::get).toArray()));}
 private Receipt receipt(Loaded loaded,Map<String,Object> row)throws IOException{return decoder.treeToValue(schema.read(text(row,"receipt_json")),Receipt.class);}
 private JsonNode receiptDocument(String kind,JsonNode content,String operation,String contentHash){boolean author="AUTHOR".equals(kind);return json.tree(new Receipt(new PermissionProtocol.Basis(content.required("version_id").asText(),author?contentHash:content.required("binding_sha256").asText()),author?"DRAFT":content.required("status").asText(),author?"1":content.required("revision").asText(),operation));}

 static String transition(String before,String decision){return switch(before+":"+decision){case "DRAFT:APPROVE"->"APPROVED";case "DRAFT:REJECT"->"REJECTED";case "APPROVED:DISABLE"->"DISABLED";default->throw new TenantAccessException(ErrorCode.REVISION_CONFLICT);};}
 private static <T>T one(List<T> rows){if(rows.size()!=1)bad();return rows.get(0);}private static void changed(int n){if(n!=1)deny(ErrorCode.REVISION_CONFLICT);}
 private LocalDateTime now(){return Objects.requireNonNull(permissions.databaseTime());}private static LocalDateTime time(Map<String,Object> row,String field){Object value=row.get(field);if(value instanceof LocalDateTime t)return t;if(value instanceof java.sql.Timestamp t)return t.toLocalDateTime();bad();return null;}
 private static String text(Map<String,Object> row,String field){if(row.get(field) instanceof String s)return s;bad();return null;}private static BigInteger number(Map<String,Object> row,String field){if(row.get(field) instanceof Number n)return new BigInteger(n.toString());bad();return null;}
 private static String instant(LocalDateTime now){return now.toInstant(ZoneOffset.UTC).toString();}private static String id(){return UUID.randomUUID().toString();}private static String sha(String s){return org.apache.commons.codec.digest.DigestUtils.sha256Hex(s);}private static void key(String s){if(s==null||!s.matches("[!-~]{16,128}"))deny(ErrorCode.SCHEMA_INVALID);}
 private static void bad(){deny(ErrorCode.CONTENT_MISMATCH);}private static void deny(ErrorCode code){throw new TenantAccessException(code);}
}
